    TeamMail.on(rid => { if (W.dlg.open && (rid == null || rid === W.rid)) thread(); });
    // the thread is shared with the engraving cards: a read, from here or from a card, draws it again
    TeamMail.onThread(rid => { if (W.dlg.open && rid === W.rid) thread(); });
