  const GROUP_NOW = { order: "Order in", review: "In review", engrave: "Engraving", sheet: "On a sheet", label: "Labelled", laser: "Laser cut", station: "At the stations", ship: "At shipping", done: "Completed", cancel: "Cancelled", note: "" };
