    const left = Math.max(0, (state.nextCheck || real + interval()) - real) * (sim && !quiet() ? Sandbox.speed() : 1), wait = sim && !busy && !left ? held() : "";
    const inbox = Recall.on() && state.inbox?.length ? `${state.inbox.length} orders available · click to open · ` : "";
