      if (page?.charms.length) continue;
      if (!S.cloud.ok) throw new Error("Reconnect to finish saving the re-optimized set");
      await api("charmNestLibrary", { op: "archiveEmptySheet", id, runId: run.runId });
      delete run.sheets[id];
